        assert!(is_word_boundary(&['a', '/', 'b'], 2));
        assert!(is_word_boundary(&['a', '.', 'b'], 2));
        assert!(is_word_boundary(&['a', 'B'], 1));
        assert!(!is_word_boundary(&['a', 'b', 'c'], 1));
        assert!(!is_word_boundary(&['A', 'B', 'C'], 1));
    }
}

